<script setup>
import {computed} from 'vue';
import NumberRange from './NumberRange.vue';
import {normalizeTypewriter} from '../typewriter.js';
const props=defineProps({value:Object}),emit=defineEmits(['change']),settings=computed(()=>normalizeTypewriter(props.value));
</script>
<template><label class="checkbox-label"><input type="checkbox" :checked="settings.enabled" @change="emit('change','enabled',$event.target.checked)">Effet machine à écrire</label><template v-if="settings.enabled"><label>Révéler par<select aria-label="Mode d’écriture" :value="settings.mode" @change="emit('change','mode',$event.target.value)"><option value="character">Caractère</option><option value="word">Mot</option></select></label><NumberRange label="Vitesse d’écriture" :model-value="settings.speed" :min="1" :max="120" :unit="settings.mode==='word'?'mots/s':'car./s'" @update:model-value="emit('change','speed',$event)"/><NumberRange label="Délai avant écriture" :model-value="settings.delay" :min="0" :max="10" :step="0.1" unit="s" @update:model-value="emit('change','delay',$event)"/><label>Curseur<select aria-label="Curseur d’écriture" :value="settings.cursor" @change="emit('change','cursor',$event.target.value)"><option value="none">Aucun</option><option value="bar">Barre clignotante</option><option value="block">Bloc clignotant</option></select></label></template><p class="field-help">Le texte s’écrit lors de son apparition en présentation ou dans une incrustation animée. Mise en page fixe ; texte complet dans l’éditeur et les PNG. Prévois une durée suffisante avant la sortie de l’incrustation.</p></template>
